//! Open questions (E3-3): `open-questions.yaml` is the source of truth; `open-questions.md` is a view regenerated after every
//! change, byte for byte as the Python app renders it (a hand-edited view is refused, not overwritten). Answering only RECORDS the
//! answer; turning it into memory changes is a separate, previewed step.
use crate::memstore::{op, EditOpts, EditResult, Store, QUESTIONS_MD};
use anyhow::{bail, Result};
use serde_json::{json, Value};

pub const YAML: &str = "open-questions.yaml";
const HEADER: &str = "# Open questions for the user\n<!-- Generated from open-questions.yaml by `coach questions`: do not edit this file by hand (it is rewritten;\n     a hand-edited copy is saved under .backups/). Use `coach questions answer|dismiss|add` instead. -->\nThe coach asks these when relevant. An answer is recorded here first, then turned into concrete changes of the\nother memory files (`categorization.yaml`, `events.md`, `liabilities/`, `contracts/`, `assets.yaml`...).\n";
const ORDER: [&str; 18] = ["id", "status", "topic", "topic_code", "question", "question_msg", "context", "context_msg", "evidence", "suggested_target", "stake", "key", "origin", "created", "answered", "answer", "note", "source_text"];

/// Python's str() of a scalar (True, 3, 3.0, a date as ISO text).
fn py_str(v: &Value) -> String { match v { Value::Null => "None".into(), Value::Bool(b) => if *b { "True".into() } else { "False".into() }, Value::String(s) => s.clone(), Value::Number(n) => crate::proposals::py_dumps(&Value::Number(n.clone())), x => x.to_string() } }
fn s<'a>(q: &'a Value, k: &str) -> Option<&'a str> { q[k].as_str().filter(|x| !x.is_empty()) }
fn legacy_answer(src: &str) -> String { match crate::rs!(r"\((?:answered\s+)?(\d{4}-\d{2}-\d{2})\)\.?\s*$").find(src) { Some(m) => src[..m.start()].trim_end().into(), None => src.into() } }
pub fn render_line(q: &Value) -> String {
    let tag = format!("`{}`", s(q, "id").unwrap_or("")); let (status, origin, question) = (s(q, "status").unwrap_or("open"), s(q, "origin").unwrap_or("manual"), s(q, "question").unwrap_or(""));
    let src = s(q, "source_text");
    match status {
        "answered" => { if let (true, Some(t), Some(a)) = (origin == "migrated", src, s(q, "answer")) { if a == legacy_answer(t) { return format!("- [x] {tag} {t}"); } }
            format!("- [x] {tag} {question} → {}{}", s(q, "answer").unwrap_or("None"), s(q, "answered").map(|d| format!(" (answered {d})")).unwrap_or_default()) }
        "dismissed" => format!("- [-] {tag} ~~{question}~~ (dismissed{}{})", s(q, "answered").map(|d| format!(" {d}")).unwrap_or_default(), s(q, "note").map(|n| format!(": {n}")).unwrap_or_default()),
        _ => { if origin == "migrated" { if let Some(t) = src { return format!("- [ ] {tag} {t}"); } }
            let mut extra = String::new();
            if let Some(ev) = q["evidence"].as_object().filter(|e| !e.is_empty()) { extra += &format!(" ({})", ev.iter().map(|(k, v)| format!("{k}={}", match v { Value::Array(a) => a.iter().map(py_str).collect::<Vec<_>>().join(","), x => py_str(x) })).collect::<Vec<_>>().join("; ")); }
            if let Some(f) = q["suggested_target"]["file"].as_str() { extra += &format!(" → `{f}`{}", q["suggested_target"]["field"].as_str().map(|x| format!(" `{x}`")).unwrap_or_default()); }
            format!("- [ ] {tag} {question}{extra}") }
    }
}
pub fn render_markdown(qs: &[Value]) -> String {
    let mut out = vec![HEADER.to_string()]; let mut topics: Vec<&str> = vec![]; for q in qs { let t = s(q, "topic").unwrap_or("General"); if !topics.contains(&t) { topics.push(t); } }
    let n = |st: &str| qs.iter().filter(|q| s(q, "status").unwrap_or("open") == st).count();
    out.push(format!("{} open, {} answered, {} dismissed.\n", n("open"), n("answered"), n("dismissed")));
    for t in topics { out.push(format!("## {t}\n")); out.extend(qs.iter().filter(|q| s(q, "topic").unwrap_or("General") == t).map(render_line)); out.push(String::new()); }
    out.join("\n").trim_end_matches('\n').to_string() + "\n"
}
pub fn listing(st: &Store, status: Option<&str>) -> Vec<Value> {
    let mut qs: Vec<Value> = st.items(YAML).into_iter().filter(|q| status.is_none_or(|x| s(q, "status").unwrap_or("open") == x)).collect();
    qs.sort_by(|a, b| (s(a, "status").unwrap_or("open") != "open").cmp(&(s(b, "status").unwrap_or("open") != "open")).then(b["stake"].as_f64().unwrap_or(0.0).total_cmp(&a["stake"].as_f64().unwrap_or(0.0)))); qs
}
pub fn md_hand_edited(st: &Store) -> bool { st.exists(QUESTIONS_MD) && st.exists(YAML) && st.read_text(QUESTIONS_MD) != render_markdown(&st.items(YAML)) }
/// The regenerated view after `ops` (for the same recorded change).
pub fn companion_after(st: &Store, ops: &[Value]) -> Result<Vec<(&'static str, String)>> {
    if md_hand_edited(st) { bail!("open-questions.md was edited by hand (or is out of date): run `coach questions regenerate-view` in the Python app first"); }
    let new = crate::memstore::yaml_edit(&st.read_text(YAML), st.exists(YAML), ops, "questions")?; let v: serde_yaml::Value = serde_yaml::from_str(&new)?;
    let qs = serde_json::to_value(v)?["questions"].as_array().cloned().unwrap_or_default(); Ok(vec![(QUESTIONS_MD, render_markdown(&qs))])
}
fn edit(st: &Store, mut ops: Vec<Value>, action: &str, reason: Option<&str>, dry_run: bool) -> Result<EditResult> {
    if !st.exists(YAML) { ops.insert(0, json!({"op": "create", "value": {"questions": []}})); }
    let extra = companion_after(st, &ops)?; st.edit_with(YAML, &ops, &EditOpts { action, reason, dry_run, ..Default::default() }, &extra)
}
fn get(st: &Store, id: &str) -> Result<Value> { st.items(YAML).into_iter().find(|q| q["id"] == id).ok_or_else(|| anyhow::anyhow!("no question {id:?}")) }
/// A question as stored: the Python app's key order, no empty evidence, no nulls.
pub fn doc(q: &Value) -> Value { let o = q.as_object().cloned().unwrap_or_default(); Value::Object(ORDER.iter().filter_map(|k| o.get(*k).filter(|v| !v.is_null() && !(*k == "evidence" && v.as_object().is_some_and(|e| e.is_empty()))).map(|v| (k.to_string(), v.clone()))).collect()) }
pub fn new_id(st: &Store) -> String { let ids: Vec<String> = st.items(YAML).iter().filter_map(|q| q["id"].as_str().map(String::from)).collect(); (1..).map(|n| format!("q-{n:03}")).find(|i| !ids.contains(i)).unwrap() }
pub fn add_ops(st: &Store, question: &str, topic: &str, origin: &str, context: Option<&str>, today: chrono::NaiveDate) -> (String, Vec<Value>) {
    let id = new_id(st); let q = doc(&json!({"id": id, "status": "open", "topic": topic, "question": question, "context": context, "origin": origin, "created": today.to_string()})); (id, vec![op("append", "questions", q)])
}
pub fn add(st: &Store, question: &str, topic: &str, today: chrono::NaiveDate, dry_run: bool) -> Result<(String, EditResult)> {
    if question.trim().is_empty() { bail!("the question is empty"); } let (id, ops) = add_ops(st, question.trim(), topic, "manual", None, today); Ok((id, edit(st, ops, "add-question", None, dry_run)?))
}
pub fn answer(st: &Store, id: &str, text: &str, today: chrono::NaiveDate, dry_run: bool) -> Result<EditResult> {
    let q = get(st, id)?; if q["status"] == "answered" { bail!("{id} is already answered; reopen it first to change the answer"); } if text.trim().is_empty() { bail!("the answer is empty"); }
    let mut ops = vec![op("set", &format!("{id}.status"), json!("answered")), op("set", &format!("{id}.answer"), json!(text.trim())), op("set", &format!("{id}.answered"), json!(today.to_string()))];
    if q.get("note").is_some_and(|n| !n.is_null()) { ops.push(op("unset", &format!("{id}.note"), Value::Null)); }
    edit(st, ops, "answer-question", Some(id), dry_run)
}
pub fn dismiss(st: &Store, id: &str, reason: Option<&str>, today: chrono::NaiveDate, dry_run: bool) -> Result<EditResult> {
    let q = get(st, id)?; if q["status"] == "answered" { bail!("{id} is answered; reopen it first"); }
    if q["status"] == "dismissed" { return Ok(EditResult { file: YAML.into(), ..Default::default() }); }
    let mut ops = vec![op("set", &format!("{id}.status"), json!("dismissed")), op("set", &format!("{id}.answered"), json!(today.to_string()))];
    if let Some(r) = reason.filter(|r| !r.trim().is_empty()) { ops.push(op("set", &format!("{id}.note"), json!(r))); }
    edit(st, ops, "dismiss-question", Some(id), dry_run)
}
pub fn reopen(st: &Store, id: &str, dry_run: bool) -> Result<EditResult> {
    let q = get(st, id)?; if q["status"] == "open" { return Ok(EditResult { file: YAML.into(), ..Default::default() }); }
    let mut ops = vec![op("set", &format!("{id}.status"), json!("open"))]; for f in ["answer", "answered", "note"] { if q.get(f).is_some_and(|v| !v.is_null()) { ops.push(op("unset", &format!("{id}.{f}"), Value::Null)); } }
    edit(st, ops, "reopen-question", Some(id), dry_run)
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test] fn renders_like_python() {
        let qs = vec![json!({"id": "q-001", "status": "open", "topic": "Merchants", "question": "What is ACME?", "evidence": {"n": 3, "total": 12.5, "months": ["2025-01", "2025-02"], "ok": true}, "suggested_target": {"file": "categorization.yaml"}}),
            json!({"id": "q-002", "status": "answered", "topic": "Merchants", "question": "Q2?", "answer": "groceries", "answered": "2025-03-01"}), json!({"id": "q-003", "status": "dismissed", "topic": "Loans", "question": "Q3?", "answered": "2025-03-02", "note": "not relevant"})];
        let md = render_markdown(&qs);
        assert!(md.ends_with("1 open, 1 answered, 1 dismissed.\n\n## Merchants\n\n- [ ] `q-001` What is ACME? (n=3; total=12.5; months=2025-01,2025-02; ok=True) → `categorization.yaml`\n- [x] `q-002` Q2? → groceries (answered 2025-03-01)\n\n## Loans\n\n- [-] `q-003` ~~Q3?~~ (dismissed 2025-03-02: not relevant)\n"), "{md}");
    }
}
